D-M-Home.css:
body{margin:0;font-family:'Baloo 2',-apple-system,BlinkMacSystemFont,'PingFang SC','Hiragino Sans GB','Microsoft YaHei','HarmonyOS Sans SC','MiSans',system-ui,sans-serif;background:#141312;color:#F2EFEA}
a{color:#FFB27A;text-decoration:none}a:hover{color:#FFC9A3}
button,a{transition:transform .12s ease,box-shadow .15s ease,filter .15s ease,background-color .15s ease}
button:not(:disabled):active,a:active{transform:translateY(1px) scale(.99)}
button:focus-visible,a:focus-visible{outline:3px solid #6C63FF;outline-offset:3px}
@keyframes pp-bob{0%,100%{transform:translateY(0)}50%{transform:translateY(-4px)}}
.pp-bob{animation:pp-bob 3.2s ease-in-out infinite}
@media (prefers-reduced-motion:reduce){.pp-bob{animation:none}}
h1,h2,h3{line-height:1.25;letter-spacing:-0.01em;text-wrap:balance}p{line-height:1.6}
body{-webkit-font-smoothing:antialiased;-moz-osx-font-smoothing:grayscale;font-variant-numeric:tabular-nums}
@keyframes pp-sheet-up{from{transform:translateY(100%)}to{transform:translateY(0)}}
@keyframes pp-toast{from{opacity:0;transform:translate(-50%,8px)}to{opacity:1;transform:translate(-50%,0)}}
@media (prefers-reduced-motion:reduce){[style*="pp-sheet-up"],[style*="pp-toast"]{animation:none!important}}

@keyframes pp-ring{0%{transform:scale(1);opacity:.55}100%{transform:scale(1.45);opacity:0}}
.pp-ring{animation:pp-ring 1.8s ease-out infinite}
@keyframes pp-hop{0%,100%{transform:translate(-50%,0)}50%{transform:translate(-50%,-5px)}}
.pp-hop{animation:pp-hop 1.6s ease-in-out infinite}
@keyframes pp-tw{0%,100%{opacity:.25;transform:scale(.8)}50%{opacity:1;transform:scale(1)}}
.pp-tw{animation:pp-tw 2.6s ease-in-out infinite}
@keyframes pp-fly{0%,100%{transform:translate(0,0) rotate(-8deg)}50%{transform:translate(6px,-6px) rotate(-4deg)}}
.pp-fly{animation:pp-fly 4s ease-in-out infinite}
@keyframes pp-pop{from{opacity:0;transform:translateY(-6px) scale(.97)}to{opacity:1;transform:none}}
.pp-popc{animation:pp-pop .18s ease-out}
.pp-node:not(:disabled):hover{filter:brightness(1.06)}.pp-node:not(:disabled):active{transform:translateY(4px)!important;box-shadow:none!important}@keyframes pp-glow{0%,100%{opacity:.55;transform:scale(1)}50%{opacity:.9;transform:scale(1.08)}}.pp-glow{animation:pp-glow 2.2s ease-in-out infinite}@keyframes pp-swipe{0%,100%{transform:translateY(2px)}50%{transform:translateY(-3px)}}.pp-swipe-a{animation:pp-swipe 1.4s ease-in-out infinite}.pp-swipe{transition:opacity .25s ease,transform .25s ease}[data-sw-top] .pp-swipe{opacity:0;transform:translateY(-8px) scale(.96)}@media (prefers-reduced-motion:reduce){.pp-glow,.pp-swipe-a{animation:none}}
.pp-scroll{scrollbar-width:none}.pp-scroll::-webkit-scrollbar{display:none}
@media (prefers-reduced-motion:reduce){.pp-ring,.pp-hop,.pp-tw,.pp-fly,.pp-popc{animation:none}}

@keyframes pp-lit{0%{transform:scale(.55);filter:grayscale(1) brightness(1.2)}55%{transform:scale(1.15);filter:none}100%{transform:scale(1)}}
.pp-lit{animation:pp-lit .75s cubic-bezier(.3,1.4,.5,1) .45s backwards}
@keyframes pp-draw{from{stroke-dashoffset:900}to{stroke-dashoffset:0}}
.pp-draw{stroke-dasharray:900;animation:pp-draw 1.1s ease-out .1s backwards}
@keyframes pp-spin{to{transform:rotate(360deg)}}
.pp-rays{animation:pp-spin 18s linear infinite}
@keyframes pp-popin{0%{transform:scale(.6);opacity:0}60%{transform:scale(1.06);opacity:1}100%{transform:scale(1)}}
.pp-popin{animation:pp-popin .45s cubic-bezier(.3,1.3,.5,1) both}
@keyframes pp-glowp{0%,100%{box-shadow:0 0 0 0 rgba(250, 117, 24,.45)}50%{box-shadow:0 0 0 6px rgba(250, 117, 24,0)}}
.pp-claim{animation:pp-glowp 1.6s ease-out infinite}
@keyframes pp-sheet-up2{from{transform:translateY(100%)}to{transform:none}}
.pp-sheet{animation:pp-sheet-up2 .3s cubic-bezier(.2,.9,.3,1)}
@media (prefers-reduced-motion:reduce){.pp-lit,.pp-draw,.pp-rays,.pp-popin,.pp-claim,.pp-sheet{animation:none}}
/*pp-mg*/a[style*="inset 0 -4px 0 rgba("]:active,button[style*="inset 0 -4px 0 rgba("]:not(:disabled):active,a[style*="inset 0 -2px 0 rgba(0,0,0,.06)"]:active,button[style*="inset 0 -2px 0 rgba(0,0,0,.06)"]:not(:disabled):active{transform:scale(.96)!important;filter:brightness(.97)!important}.mg-nav a:active .mg-ni{transform:scale(.9)}@keyframes mg-pop{0%{transform:scale(.4);opacity:0}70%{transform:scale(1.08)}100%{transform:scale(1);opacity:1}}.mg-pop{animation:mg-pop .55s cubic-bezier(.3,1.4,.5,1) both}@keyframes mg-float{0%,100%{transform:translateY(0)}50%{transform:translateY(-7px)}}.mg-float{animation:mg-float 2.8s ease-in-out infinite}@keyframes mg-drift{0%,100%{transform:translateX(0)}50%{transform:translateX(12px)}}.mg-cloud{animation:mg-drift 9s ease-in-out infinite}@media (prefers-reduced-motion:reduce){.mg-pop,.mg-float,.mg-cloud{animation:none}}/*pp-calm*/main{scrollbar-width:none}main::-webkit-scrollbar{display:none}main[style*="mask-image"]::after{content:"";display:block;flex-shrink:0;height:16px}.mg-float,.mg-cloud,.pp-shake,.pp-flick,.pp-tw,.pp-twinkle,.pp-fly,.pp-steam,.pp-ring,.pp-bob,.pp-rays{animation:none!important}.pp-conf{animation-iteration-count:1!important;animation-fill-mode:forwards!important}.pp-claim{animation-iteration-count:3!important}/*pp-glassbtn*/a[style*="inset 0 -2px 0 rgba(0,0,0,.06)"]:active,button[style*="inset 0 -2px 0 rgba(0,0,0,.06)"]:not(:disabled):active{transform:scale(.97)!important;filter:brightness(.95)!important}/*pp-mainfix*/main[style*="overflow-y: auto"]>*{flex-shrink:0}

